/**
 * A execução termina VERMELHA quando algo não saiu: resumo sem ninguém para receber ou toque
 * que a Evolution recusou. Fila que falha calada é fila que ninguém audita.
 */
const r = $input.first().json;
if (r.statusCode !== 200) {
  throw new Error('A rodada do atendimento respondeu HTTP ' + r.statusCode + ': ' + JSON.stringify(r.body).slice(0, 300));
}
const corpo = r.body || {};
if (corpo.falhas > 0) {
  const toques = (corpo.toques || []).filter((t) => t.enviado === false).map((t) => t.lead_id + ' (' + (t.motivo || '?') + ')');
  const entregas = (corpo.entregas || []).filter((e) => e.avisado === false && e.motivo === 'sem_destinatario').map((e) => e.lead_id);
  throw new Error('RODADA COM FALHA: ' + corpo.falhas + '. Toques não enviados: ' + (toques.join('; ') || 'nenhum')
    + '. Entregas sem destinatário: ' + (entregas.join('; ') || 'nenhuma') + '.');
}
return [{ json: { ativo: corpo.ativo, entregas: (corpo.entregas || []).length, toques: (corpo.toques || []).length } }];
